 const parseImport=async file=>{
  setModalItems([]);setError('');if(!file)return;
  const xlsx=/\.xlsx$/i.test(file.name);
  if(xlsx?file.size>5000000:file.size>2000000){setError(xlsx?'El archivo Excel no puede superar 5 MB.':'El archivo CSV no puede superar 2 MB.');return}
  try{
   // DM-01: Excel y CSV comparten columnas y validaci\u00F3n (product-import.mjs).
   const {productTableRecords,validateProductImport}=await loadProductImport();let source;
   if(xlsx)source=productTableRecords(await (await loadExcel()).readProductExcel(await file.arrayBuffer()));
   else{const Papa=await loadPapa();const parsed=Papa.parse(await file.text(),{header:true,skipEmptyLines:'greedy',transformHeader:h=>h.replace(/^\uFEFF/,'').trim()});source={headers:parsed.meta.fields||[],rows:parsed.data,problems:parsed.errors.map(e=>`Fila ${Number(e.row||0)+2}: ${e.message}`)}}
   const {items,problems,examples}=validateProductImport({...source,prods});
   setModalForm({fileName:file.name,errors:problems.slice(0,30),errorCount:problems.length,examples});
   if(!problems.length)setModalItems(items);
  }catch(failure){setError(failure.message||`No se pudo leer el archivo ${xlsx?'Excel':'CSV'}.`)}
 };
