  {view==='garantias'&&features.includes('garantias')&&<WarrantiesView key={warrantySale||'warranties'} state={state} session={session} admin={admin} company={company} onAction={onAction} onRetryAction={onRetryAction} focusSaleId={warrantySale}/>}
  {view==='proveedores'&&admin&&<PurchasingView state={state} admin={admin} company={company} features={features} onAction={onAction} onRetryAction={onRetryAction}/>}
  {view==='dashboard'&&admin&&showSetup&&setupWizard}
