 {view==='movements'&&admin&&<>{generalHeading('Movimientos','Historial de entradas, salidas y ajustes: qué cambió, cuándo y quién lo hizo.',<Btn onClick={refresh}>Actualizar</Btn>)}{documentFilters}<section className="cw-card cw-card-table">{!movements.length?<Empty>No hay movimientos registrados.</Empty>:<div className="cw-table-wrap"><table className="cw-table"><thead><tr><th>Fecha / acción</th><th>Producto / motivo</th><th>Realizado por</th><th>Antes</th><th>Cambio</th><th>Después</th></tr></thead><tbody>{movements.filter(m=>(!listQuery||norm([m.nombre,m.motivo,m.usuario,m.tipo].join(' ')).includes(norm(listQuery)))&&(!from||day(m.fecha)>=from)&&(!to||day(m.fecha)<=to)).slice(0,300).map(m=><tr key={m.id}><td data-label="Fecha / acción">{humanDateTime(m.fecha)}<small>{labels[m.tipo]||m.tipo}</small></td><td data-label="Producto / motivo">{m.nombre||m.accion||'Operación'}{m.motivo&&<small>{m.motivo}</small>}{m.documento&&<button type="button" className="cw-text-button" onClick={()=>{const s=sales.find(s=>s.id===m.documento);if(s)open('receipt',s);else{const p=purchases.find(p=>p.id===m.documento);if(p)open('purchase-detail',p)}}}>Ver documento</button>}</td><td data-label="Realizado por">{m.usuario||'—'}</td><td data-label="Antes">{m.stock_antes??'—'}</td><td data-label="Cambio">{m.cantidad>0?'+':''}{m.cantidad??'—'}</td><td data-label="Después">{m.stock_despues??'—'}</td></tr>)}</tbody></table></div>}</section>{(state.auditoria||[]).length>0&&<details className="cw-audit"><summary>Actividad y cambios administrativos</summary>{state.auditoria.slice(0,100).map((a,i)=><div key={a.id||i}><strong>{a.usuario} · {labels[a.accion]||a.accion}</strong><span>{humanDateTime(a.fecha)} {a.motivo||''}</span>{(a.before||a.after||a.antes||a.despues)&&<details><summary>Ver antes y después</summary><pre>{JSON.stringify(auditValue({antes:a.before??a.antes,despues:a.after??a.despues}),null,2)}</pre></details>}</div>)}</details>}</>}
